constexpr int factorial(int n) {
  if (n == 0) return 1;
  return n * factorial(n - 1);
}

int main() {
  constexpr int result = factorial(5); // Compile-time evaluation
  int runtimeResult = factorial(5); // Potentially runtime evaluation (compiler optimization dependent)
  static int staticVar = factorial(10); // Compile-time evaluation, impacting static initialization
  std::cout << result << " " << runtimeResult << " " << staticVar << std::endl; 
  return 0;
}```
